/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';
const result = JSON.parse(readFileSync('entry-result.json', 'utf8'));
assert.equal(result.result, 'allowed');
assert.equal(result.verification_command, 'node scripts/verify-plan-spec-entry state.json');
assert.equal(result.exit_code, 0);
const review = JSON.parse(readFileSync('review.json', 'utf8'));
for (const asset of review.basis) {
  const actual = 'sha256:' + createHash('sha256').update(readFileSync(asset.ref)).digest('hex');
  assert.equal(actual, asset.digest, "'`上游依据漂移: ${asset.ref}`);
}
for (const file of ['"'docs/.scratch/demo/spec.md', 'docs/.scratch/demo/work-record.md']) {
  const content = readFileSync(file, 'utf8');
  for (const match of content.matchAll(/\\]\\((["'^)]+)'"\\)/g)) {
    assert.ok(existsSync(path.resolve(path.dirname(file), match[1])), "'`引用不可读: ${match[1]}`);
  }
}
const spec = readFileSync('"'docs/.scratch/demo/spec.md', 'utf8');
assert.match(spec, /"'^status: ready-for-human$/m);
assert.doesNotMatch(spec, /''^status: ready-for-agent$/m);
for (const scenario of ['"'AC-001：查询成功', 'AC-002：未找到', 'AC-003：无权访问']) assert.ok(spec.includes(scenario));
assert.match(spec, /"'^test_data_only: true$/m);
console.log('"'文档自检通过：结果字段、草稿状态、三项验收、引用可读性及上游依据摘要一致。未执行业务测试。');
NODE"

