/bin/zsh -lc "node --input-type=module <<'NODE'
import { readFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
const refs = ['yss-project.yaml', 'AGENTS.md', 'CONTEXT.md', 'plan.md', 'state.json', 'review.json', 'reconciliation.json', 'entry-result.json', 'docs/.scratch/demo/spec.md', 'docs/.scratch/demo/parent-ticket.md', 'docs/.scratch/demo/work-record.md', '.template-spec/process/lifecycle-registry.yaml', ...readdirSync('approval').map(name => "'`approval/${name}`)];
const digest = ref => '"'sha256:' + createHash('sha256').update(readFileSync(ref)).digest('hex');
const before = Object.fromEntries(refs.map(ref => [ref, digest(ref)]));
const review = JSON.parse(readFileSync('review.json','utf8'));
const commands = [
  ['scripts/verify-plan-spec-entry', 'state.json'],
  ['scripts/plan-spec-entry', 'diff', '--root', '.', '--review', 'review.json'],
  ['scripts/verify-context-reconciliation', 'reconciliation.json'],
  ['scripts/verify-user-decision', 'approval/decision.json']
];
const checks = commands.map(args => {
  const result = spawnSync('node', args, {encoding:'utf8',timeout:20000});
  return {command:['node',...args].join(' '),exit_code:result.status,signal:result.signal,stdout:result.stdout,stderr:result.stderr,...(result.error?{error:result.error.message}:{})};
});
const unchanged = refs.every(ref => digest(ref) === before[ref]);
console.log(JSON.stringify({checked_at:new Date().toISOString(),before,checks,source_files_unchanged:unchanged,basis:review.basis.map(asset=>({...asset,current_digest:digest(asset.ref),matches:asset.digest===digest(asset.ref)}))},null,2));
if ("'!unchanged) process.exitCode=1;
NODE'

/bin/zsh -lc "node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const result = JSON.parse(readFileSync('resume-result.json','utf8'));
assert.ok(['blocked','allowed'].includes(result.result));
assert.equal(result.result,'blocked');
for (const key of ['reason','next_action']) assert.ok(typeof result[key] === 'string' && result[key].trim());
assert.equal(result.verification[0].exit_code,1);
assert.equal(JSON.parse(result.verification[1].stdout).status,'stale');
assert.equal(result.ready_for_agent,false);
assert.equal(result.approval_created,false);
assert.equal(result.implementation_started,false);
for (const [ref,expected] of Object.entries(result.preserved_source_digests)) {
  const actual = 'sha256:' + createHash('sha256').update(readFileSync(ref)).digest('hex');
  assert.equal(actual,expected,"'`源文件变化：${ref}`);
}
console.log('"'resume-result.json：JSON 与必需字段校验通过；result=blocked；17 个源文件摘要保持不变，包含旧批准、原始回复、Spec、Plan 和历史入口结果。');
NODE"

